// ---------------------------------------------------------------- the build's pace
// THE ENGINE HANDS THE PAGE BACK at the first ask that comes six milliseconds or more after the last hand-back, and
// each hand-back waits for the page's next frame. A build that asks after every small piece is therefore cut into
// slices of six or seven milliseconds with a frame spent on each (a build that asks some 2,470 times is two and
// a half times its own work long). So every ask of this build goes through a count of work: the ask says about how many
// milliseconds the piece that FOLLOWS it takes (figures read from the build's own trace and
// typed at each place; BUILD_PACE.PLAIN where nothing is said), and the engine is asked only when what is gathered
// since the last hand-back and the piece to come are together more than BUILD_PACE.PIECE, or when the piece to come
// is a dear one (DEAR or more) and SOME work is gathered already, so that a dear piece begins a slice of its own.
// No clock is read anywhere: the figures stand in the code, and the same asks reach the engine at the same places on
