    // a square plinth of blue stone, a moulded base (two rounds and a hollow: INVENTED profile), the fluted shaft
    B.box(x - 0.66, y0, z - 0.66, x + 0.66, y0 + M.PLINTH_H, z + 0.66, COL.blue, 2);
    B.spine([[x, y0 + 0.35, z], [x, y0 + 0.47, z], [x, y0 + 0.56, z], [x, y0 + 0.68, z], [x, y0 + 0.8, z]], [0.64, 0.66, 0.55, 0.6, 0.5], mb, 9, { seg: 14, up: [1, 0, 0] });
    B.spine([[x, y0 + 0.8, z], [x, y0 + 4.6, z], [x, y0 + 8.75, z]], [M.COL_D / 2, 0.485, 0.43], mb, 15, { seg: 14, up: [1, 0, 0] });
    // the capital: a swelling round under a cushion that ends in a volute at each side, front and back, and a thin slab
    B.spine([[x, y0 + 8.75, z], [x, y0 + 8.9, z], [x, y0 + 9.02, z]], [0.43, 0.5, 0.58], mb, 9, { seg: 14, up: [1, 0, 0] });
    const cy = y0 + 9.16;
