      const onClimb = (hx1 === M.CLIMB_X - M.CLIMB_W / 2 || hx0 === xE) && hz1 > M.SQUARE_Z1 && hz0 < M.MARKET_Z0;
      const h = onClimb ? 2.9 + 0.4 * tone : hgt;
