// the light sea wind blows to the north-east; a ship at anchor lies with her head to it (to the south-west)
export const WIND = [0.7071, -0.7071], WIND_YAW = Math.atan2(-0.7071, 0.7071);
// THE ANCHORAGE'S RULE (INVENTED): ships lie to single anchors either side of the fairway, each with her head to the
// wind, in files along the fairway. A BERTH is the place where the hull lies in the mean wind (her anchor lies a
// cable's scope upwind of it). The nearest file's berths lie a ship's length and a half from the fairway's edge; the
// next file three ship's lengths further out (the swinging room of two ships); along a file the berths are three
// ship's lengths apart, the first three lengths off the quay, the last inside the line where the warship turns before
// the mouth. ON THE WEST HAND the warship's lane (the brief's: 35 m west of the fairway's middle) takes the place of
// the nearest file: there the merchantmen's files lie inside her round, the first a length and a half inside her oar
// tips, their first berths level with her north turn's centre (where her lane begins) and the rest three ship's
// lengths apart to the south as on the east hand. THE SMALL BOATS' MOORINGS (boats of 7 m, each on a short mooring)
// lie along the fairway's west edge between and beyond the two lightering berths there, north of the warship's lane
// (WEST_EDGE): south of them her lane runs beside the fairway, and the strip between the fairway's edge and the sea
// room of her blades (8.4 m) is too narrow for a boat to swing in (she needs about 9.4 m).
// WHICH BERTHS ARE HELD: a master anchors as near the landing's fairway as he finds room (the lighters' pull to the
// quay is shortest from there), so the file along the fairway fills first: a berth of a nearest file is held on a lot
// under 0.85, a berth of an outer file on a lot under 0.4 (`take`), and of the file along the fairway's east edge
// the berth of the lowest lot always.
// THE LIGHTERING BERTHS (INVENTED): a ship that works her cargo into lighters lies close along the fairway's
// edge, MOORED HEAD AND STERN on two anchors so that she does not swing into the fairway: her berth's middle lies
// 0.6 of a ship's length off the fairway's edge (NEAR_OFF from its middle: at her largest size and at the reach of
// her small swing her quarter still clears the edge), head to
// the wind like the rest. Such berths lie three ship's lengths apart along each edge: on the east hand the second
// and the third off the quay (the water nearer the quay there is the lighters' way to the east quay), on the west
// hand the first and the second (further out the warship's lane leaves no room beside the fairway). On each hand
// the berth of the lower lot is always held, the other on a lot under 0.7; a ship lying there has come in with the
// afternoon's wind and has her sail hoisted on the yard to dry. A lightering berth takes the place of the small
// boats' mooring there. THE WATER ROUND THE PLACE WHERE A VISITOR COMES IN (ENTRY: the design keeps it open: 20 m to
// either side from 15 m ahead of it to 60 m behind it) holds no berth and no mooring: the moorings' file ends north of it.
export const ENTRY_BOX = { x0: ENTRY[0] - 20, x1: ENTRY[0] + 20, z0: ENTRY[2] - 15, z1: ENTRY[2] + 60 };
export const ANCHORAGE = (() => {
  const gap = 3 * SHIP_L, near = FAIRWAY / 2 + 1.5 * SHIP_L, berths = [], boats = [], zN = M.QUAY_Z + gap, zS = WARSHIP.zs;
  for (let z = zN; z <= zS; z += gap) for (const f of [0, 1]) berths.push([M.CLIMB_X + near + f * gap, z, f]);
  const wx = WARSHIP.lane - WARSHIP.reach - 1.5 * SHIP_L;
  for (let z = WARSHIP.zn; z <= zS; z += gap) for (const f of [0, 1]) berths.push([wx - f * gap, z, f]);
  const zl = (i) => M.QUAY_Z + 1.5 * SHIP_L + i * gap, lighter = [[M.CLIMB_X + NEAR_OFF, zl(1), 1], [M.CLIMB_X + NEAR_OFF, zl(2), 1], ...WEST_EDGE.filter((e) => e[3] === 'berth').map((e) => [e[0], e[1], -1])];
  // the small boats' moorings (none round the place where a visitor comes in)
  for (const e of WEST_EDGE) if (e[3] === 'mooring' && e[1] <= ENTRY_BOX.z0 - 10) boats.push([e[0], e[1]]);
  return { berths, boats, lighter, scope: 22, swing: 0.2, nearSwing: 0.03, boatScope: 5, boatSwing: 0.25, take: [0.85, 0.4], takeNear: 0.7 };
})();
