// THE FLOCKS, each on a closed loop laid by the place (INVENTED). Each record is what the kit is handed: the loop
// (for the gulls a centre, radius, wobble and height: the kit lays nine points round the centre at radius x (1 +-
// wobble), rising and falling by the height; for the pigeons and the swifts the loop's own points), the spread of
// the birds' dealt places about the loop (sideways, upright, and how far they string out along it), the birds' own
// wander, their number, and maxSigma 2.5 (the bound on a dealt place, in live's kit). `bird` is one bird's length
// and half span at its largest size: the room the animal itself takes beyond the place it is dealt.
//   THE GULLS keep about the hulls made fast at the quay's two ends, where the catch and the galley scraps are: one
//   flock wheeling low over the west quay's berths, one over the east quay's (each about a berth's middle, some
//   13 m over the water, as high as the mastheads and a little over).
//   THE PIGEONS wheel round the tomb at the middle height of its columns, PIGEON_OFF (6 m) outside the cornice all
//   the way round (straight along each side, round each corner).
//   THE SWIFTS hunt along the cypress row and over the terrace's south wall: one flock to each half of the row, on
//   a long loop about the wall's line: down the terrace's side of the row (SWIFT_IN: 2 m inside the row's line),
//   round over the wall, back along outside the wall at the same distance from it, at the height of the wall's head
//   and a little over.
// a closed loop round a rectangle (half sizes hx, hz about cx, cz) at the distance r outside it (straight along the
// sides, a quarter circle round each corner), at the height y, rising and falling by `rise` twice round; a point
// about every `step` metres
export function roundLoop(cx, cz, hx, hz, r, y, rise, step = 2) {
  const pts = [], side = (x0, z0, x1, z1) => { const n = Math.max(1, Math.round(Math.hypot(x1 - x0, z1 - z0) / step)); for (let i = 0; i < n; i++) pts.push([lerp(x0, x1, i / n), 0, lerp(z0, z1, i / n)]); };
  const corner = (px, pz, a0) => { const n = Math.max(3, Math.round(r * Math.PI / 2 / step)); for (let i = 0; i < n; i++) { const a = a0 + (i / n) * Math.PI / 2; pts.push([px + r * Math.cos(a), 0, pz + r * Math.sin(a)]); } };
  side(cx - hx, cz - hz - r, cx + hx, cz - hz - r); corner(cx + hx, cz - hz, -Math.PI / 2);
  side(cx + hx + r, cz - hz, cx + hx + r, cz + hz); corner(cx + hx, cz + hz, 0);
  side(cx + hx, cz + hz + r, cx - hx, cz + hz + r); corner(cx - hx, cz + hz, Math.PI / 2);
  side(cx - hx - r, cz + hz, cx - hx - r, cz - hz); corner(cx - hx, cz - hz, Math.PI);
  pts.forEach((q, i) => { q[1] = y + rise * Math.sin((i / pts.length) * 4 * Math.PI); });
  return pts;
}
const ROW_HALF = (M.CYPRESS_X1 - M.CYPRESS_X0) / 2, SWIFT_R = M.TER_Z1 - (M.CYPRESS_Z - SWIFT_IN);
const swifts = (name, x, keep) => ({ name, keep, species: 'swifts', size: SWIFT_SIZE, speed: SWIFT_SPEED, bird: 0.57 * SWIFT_SIZE * 1.12, n: 14, loop: roundLoop(x, M.TER_Z1, ROW_HALF / 2 - SWIFT_R, 0, SWIFT_R, M.TER_WALL_TOP + 2, 0.8), spread: [1.2, 0.8, 30], wander: [0.6, 0.5, 0.6, 0.5] });
