// HOW FAR A BIRD STRAYS FROM ITS FLOCK'S LOOP (the owner's measure of a flock's reach): 2.5 x 0.45 of the spread + one and
// a half times the wander + a bird's size, sideways (h) and upright (v). A loop the kit lays itself (the gulls') is
// taken as the whole disc of its largest radius (radius x (1 + wobble), and 1.12 for the curve the kit draws through
// its nine points), rising and falling by 1.2 x its height.
export const flockStray = (f) => ({ h: 2.5 * 0.45 * f.spread[0] + 1.5 * Math.max(f.wander[0], f.wander[2]) + f.bird, v: 2.5 * 0.45 * f.spread[1] + 1.5 * f.wander[1] + f.bird });
export const flockDisc = (f) => ({ r: f.radius * (1 + f.wobble) * 1.12, rise: 1.2 * f.height });
// THE COUNT OF A FLOCK: the least clear air between the flown line (pts: its points [x, y, z] every half metre) and
// the flock's whole reach (its loop's points, taken a metre fat for the spaces between them, or its disc; with its
// birds' stray sideways and upright). Returns [metres, the index of the line's point].
export function flockClear(f, pts) {
  const s = flockStray(f), c = f.loop ? null : flockDisc(f); let best = 1e9, at = 0;
  for (let i = 0; i < pts.length; i++) { const p = pts[i]; let v = 1e9;
    if (f.loop) for (const q of f.loop) { const dh = Math.max(0, Math.hypot(p[0] - q[0], p[2] - q[2]) - s.h - 1), dv = Math.max(0, Math.abs(p[1] - q[1]) - s.v); v = Math.min(v, Math.hypot(dh, dv)); }
    else v = Math.hypot(Math.max(0, Math.hypot(p[0] - f.center[0], p[2] - f.center[2]) - c.r - s.h), Math.max(0, Math.abs(p[1] - f.center[1]) - c.rise - s.v));
    if (v < best) { best = v; at = i; } }
  return [best, at];
}
// a flock whose count is under KEEP_UNDER is also handed the kit's own guard (keepClear, see the world's flock calls).
// THE COUNT IS NOT MADE AT BUILD: the loops and the flown line are the same on every visit, so which flocks pass
// within KEEP_UNDER of the line is a standing fact of the place. It stands in the table as `keep` (the pigeons round
// the tomb, 9.3 m; the swifts of the row's east half, 5.5 m, whose loop lies by the gate's axis; the west half's
// swifts, 28 m, and the gulls have none), with the names of the two places of the flight between which the line
// passes that flock's ground; flockClear (above) gives the count for any flock and the line's points, and the table
// is true where it agrees for every flock.
export const KEEP_UNDER = 10;
