export const placeDist = (x, z, town = false) => { let d = 1e9; for (let i = 0; i < (town ? 3 : 4); i++) { const r = PLACES[i].r; d = Math.min(d, Math.hypot(Math.max(r[0] - x, 0, x - r[2]), Math.max(r[1] - z, 0, z - r[3]))); } return d; };
export const TOWN = { NEAR: 45, FAR: 150 };
// THE WAYS THAT PEOPLE KEEP OFF (the first three each a named way of the place's own plan, laid from
// the plan's own points, with its breadth as a street has one; THE FOURTH IS THE VISITOR'S OWN WAY OVER THE TERRACE:
// said below and SAID IN THE OPEN at the head, (c)):
//   THE CART WAY THROUGH THE MARKET: from the landing at the quay's edge straight up the market's open middle to the
//     mouth of the climbing street (the worn track of the paving: carts and loads go up it);
//   THE CLIMBING STREET WITH THE UPPER SQUARE: the shop street from its mouth to its head at the square's south
//     edge, and on across the square straight to the stair's foot (the paving's worn track);
//   THE STAIR'S APPROACH: the gate's axis from the stair's foot up the stair and through the passage to the gate's
//     inner mouth;
//   THE GATE'S AXIS OVER THE TERRACE: from the gate's inner mouth west along the axis over the raked gravel, past the
//     tomb's south side, and round the turn west of the tomb as far as the turn's west point (the route's TURN2).
//     WEST OF THE AXIS'S END (where the flown line bears off) THIS WAY IS THE FLOWN LINE'S OWN TURN AND NO THING OF
//     THE PLAN: nothing on the ground marks that arc. It is laid so that every person of the terrace keeps 20 m on
//     the plan from the visitor's way (the owner's 20 m between the eye's way and any person).
//     The raked gravel along it is not walked on: who visits the tomb keeps to the trodden path round its foot,
