  tube(B, [[0, 1.2, -0.88, 0.1, 0.13], [0, 1.24, -0.78, 0.23, 0.26], [0, 1.25, -0.55, 0.29, 0.31], [0, 1.19, -0.2, 0.285, 0.3], [0, 1.17, 0.12, 0.28, 0.305], [0, 1.19, 0.42, 0.27, 0.33], [0, 1.25, 0.68, 0.225, 0.31], [0, 1.31, 0.86, 0.13, 0.2]], col, k, { seg: sg, cap0: true, cap1: true });
  // the neck, arched and deep at the shoulder, up to the poll
  const py0 = 2.03 - hd * 0.5, pz0 = 1.07 + hd * 0.12;
  tube(B, [[0, 1.3, 0.56, 0.17, 0.3], [0, 1.52, 0.75, 0.14, 0.26], [0, 1.74, 0.9, 0.115, 0.205], [0, 1.93, 1.0, 0.098, 0.165], [0, py0, pz0, 0.088, 0.13]], col, k, { seg: fine ? 12 : 8 });
  // the head, hung from the poll, turned by headYaw about it
