  const Hp = (lx, along, off) => { const y = py0 - along * sd + off * cd, z = along * cd + off * sd; return [lx * ch + z * sh, y, pz0 - lx * sh + z * ch]; };
  const hr = [[-0.04, 0.098, 0.11], [0.1, 0.115, 0.145], [0.28, 0.088, 0.115], [0.45, 0.07, 0.085], [0.56, 0.066, 0.07], [0.61, 0.045, 0.045]];
  B.spine(hr.map((q) => Hp(0, q[0], 0)), hr.map((q) => [q[1], q[2]]), col, k, { seg: fine ? 12 : 8, cap0: true, cap1: true });
  for (const sx of [-1, 1]) B.spine([Hp(sx * 0.065, -0.02, 0.07), Hp(sx * 0.08, -0.06, 0.2)], [[0.035, 0.022], [0.008, 0.006]], col, k, { seg: 5 });
  // the cropped mane: an upright crest along the neck, and a forelock
  tube(B, [[0, 1.5, 0.47, 0.03, 0.05], [0, 1.72, 0.66, 0.04, 0.085], [0, 1.93, 0.8, 0.042, 0.09], [0, 2.09 - hd * 0.3, 0.92, 0.04, 0.08], [0, py0 + 0.1, pz0 - 0.04, 0.03, 0.04]], COL.marbleB, k, { seg: 6, cap0: true, cap1: true });
  // the tail
  tube(B, [[0, 1.3, -0.84, 0.05, 0.05], [0, 1.27, -0.98, 0.07, 0.07], [0, 0.98, -1.07, 0.09, 0.08], [0, 0.58, -1.05, 0.075, 0.06], [0, 0.32, -1.0, 0.03, 0.03]], col, k, { seg: 6, cap1: true });
  // forelegs: standing, or raised and bent when reared
  for (let i = 0; i < 2; i++) { const sx = i ? 1 : -1, f = fore[i], x = sx * 0.17;
    if (rear) tube(B, [[x, 1.2, 0.56, 0.115, 0.15], [x, 0.98, 0.72, 0.085, 0.1], [x, 0.78, 0.98 + f, 0.06, 0.065], [x, 0.52, 0.86 + f, 0.04, 0.045], [x, 0.42, 0.84 + f, 0.05, 0.055], [x, 0.33, 0.9 + f, 0.06, 0.065]], col, k, { seg: lg, cap1: true });
    else tube(B, [[x, 1.2, 0.56, 0.125, 0.17], [x, 0.92, 0.57 + 0.3 * f, 0.098, 0.125], [x, 0.6, 0.585 + 0.6 * f, 0.068, 0.078], [x, 0.24, 0.56 + 0.9 * f, 0.05, 0.057], [x, 0.11, 0.57 + f, 0.058, 0.066], [x, 0, 0.6 + f, 0.076, 0.086]], col, k, { seg: lg, cap1: true }); }
  // bridle and bit in dark bronze: noseband, browband, cheek straps, bit rings
  if (o.bridle) { const bz = COL.bronze;
    for (const [al, w, d] of [[0.3, 0.09, 0.107], [0.06, 0.112, 0.13]]) B.spine([Hp(0, al - 0.018, 0), Hp(0, al + 0.018, 0)], [[w, d], [w, d]], bz, 8, { seg: 10 });
    for (const sx of [-1, 1]) { B.spine([Hp(sx * 0.108, 0.06, 0.02), Hp(sx * 0.07, 0.44, -0.02)], [0.013, 0.013], bz, 8, { seg: 4 });
      B.lump(Hp(sx * 0.072, 0.45, -0.03), 0.02, 0.034, 0.034, bz, 8, 6, 3); } }
  // a harnessed horse: a girth round the barrel and a band across the breast, carved with the horse (the marble's own
